using System.Data;using JamunaBank.Procurement.API.DTOs;
namespace JamunaBank.Procurement.API.Repositories.Implementations;
internal static class RequisitionDetailDataSetMapper
{
 public static RequisitionDetailDto? Map(DataSet ds){if(ds.Tables.Count<1||ds.Tables[0].Rows.Count==0)return null;var h=ds.Tables[0].Rows[0];var specs=ds.Tables[2].AsEnumerable().GroupBy(r=>new{Item=r.Field<long>("REQ_ITEM_ID"),Id=r.Field<long>("ASSET_SPEC_ID"),Name=r.Field<string>("SPEC_NAME_SNAPSHOT")!,Type=r.Field<string>("SPEC_TYPE_SNAPSHOT")!,Text=r.Field<string?>("SPEC_TEXT_VALUE"),Num=r.Field<decimal?>("SPEC_NUM_VALUE"),Date=r.Field<DateTime?>("SPEC_DATE_VALUE"),Bool=r.Field<bool?>("SPEC_BOOL_VALUE")}).ToDictionary(g=>(g.Key.Item,g.Key.Id),g=>new RequisitionSpecificationValueDto(g.Key.Id,g.Key.Name,g.Key.Type,g.Key.Text,g.Key.Num,g.Key.Date is DateTime d?DateOnly.FromDateTime(d):null,g.Key.Bool,g.Where(r=>r.Field<long?>("ASSET_SPEC_OPTION_ID").HasValue).Select(r=>new SelectedSpecificationOptionDto(r.Field<long>("ASSET_SPEC_OPTION_ID"),r.Field<string>("SELECTED_OPTION_TEXT_SNAPSHOT")!)).ToArray()));var replacements=ds.Tables[3].AsEnumerable().ToDictionary(r=>r.Field<long>("REQ_ITEM_ID"),r=>new ReplacementInfoDto(r.Field<string?>("ASSET_TAG_NO"),r.Field<string?>("SERIAL_NO"),r.Field<string>("CURRENT_CONDITION")!,r.Field<string?>("ADDITIONAL_INFO")));var items=ds.Tables[1].AsEnumerable().Select(r=>{var iid=r.Field<long>("REQ_ITEM_ID");return new RequisitionItemDto(iid,r.Field<long>("ASSET_ID"),r.Field<string>("ITEM_NAME_SNAPSHOT")!,r.Field<string>("REQ_TYPE")!,r.Field<decimal>("QUANTITY"),r.Field<decimal>("ESTIMATED_UNIT_PRICE"),r.Field<string>("PURPOSE_JUSTIFICATION")!,r.Field<string?>("ADDITIONAL_SPEC_REQUIREMENT"),specs.Where(s=>s.Key.Item==iid).Select(s=>s.Value).ToArray(),replacements.GetValueOrDefault(iid));}).ToArray();var attachments=ds.Tables[4].AsEnumerable().Select(r=>new AttachmentDto(r.Field<long>("ATTACHMENT_ID"),r.Field<string>("ENTITY_TYPE")!,r.Field<long>("ENTITY_ID"),r.Field<string>("FILE_NAME")!,r.Field<string>("ORIGINAL_FILE_NAME")!,r.Field<string?>("FILE_EXTENSION"),r.Field<string?>("MIME_TYPE"),r.Field<long>("FILE_SIZE"),r.Field<string?>("DOCUMENT_TYPE"),r.Field<DateTime>("UPLOADED_DATE"))).ToArray();return new(h.Field<long>("REQUISITION_ID"),h.Field<string>("REQUISITION_NO")!,h.Field<string>("REQUESTED_BY_EMPLOYEE_ID")!,h.Field<long>("REQUESTED_ORG_UNIT_ID"),h.Field<string>("ORG_UNIT_NAME")!,h.Field<DateTime>("REQUESTED_DATE"),h.Field<string>("JUSTIFICATION")!,h.Field<decimal>("TOTAL_ESTIMATED_AMOUNT"),h.Field<string>("CURRENT_STATUS")!,items,attachments);}
}
